syntax = "proto3";

package frameinventory.v1;

option java_package = "com.global.ct.frameinventory.grpc.v1";
option java_multiple_files = true;
option java_outer_classname = "FramesProto";

import "google/protobuf/empty.proto";
import "google/protobuf/timestamp.proto";

service FrameManagement {
  rpc ListFrames(ListFramesRequest) returns (ListFramesResponse);
  rpc GetFrame(GetFrameRequest) returns (Frame);
  rpc GetFrameHistory(GetFrameHistoryRequest) returns (GetFrameHistoryResponse);
  rpc CreateFrame(CreateFrameRequest) returns (Frame);
  rpc UpdateFrame(UpdateFrameRequest) returns (Frame);
  rpc DeleteFrame(DeleteFrameRequest) returns (google.protobuf.Empty);
}

message ListFramesRequest {
  // Zero-based page. Defaults to 0.
  optional int32 page = 1;
  // Defaults to 25. Valid values are 1 through 50.
  optional int32 size = 2;
}

message ListFramesResponse {
  repeated Frame items = 1;
  int32 page = 2;
  int32 size = 3;
  bool has_next = 4;
}

message GetFrameRequest {
  string frame_id = 1;
}

message GetFrameHistoryRequest {
  string frame_id = 1;
}

message GetFrameHistoryResponse {
  // Newest first, with version ID descending as a tie break.
  repeated Frame versions = 1;
}

message CreateFrameRequest {
  // A case-sensitive identifier that can be used only once.
  string frame_id = 1;
  FrameData attributes = 2;
}

message UpdateFrameRequest {
  string frame_id = 1;
  // Must match the current version.
  int64 expected_version_id = 2;
  // Replaces writable attributes. Omitted optional fields are cleared.
  FrameData attributes = 3;
}

message DeleteFrameRequest {
  string frame_id = 1;
  // If absent the delete applies to the current version.
  optional int64 expected_version_id = 2;
}

message Frame {
  string frame_id = 1;
  int64 version_id = 2;
  google.protobuf.Timestamp valid_from = 3;
  google.protobuf.Timestamp valid_to = 4;
  bool current = 5;
  optional string change_source = 6;
  optional string closed_by_change_source = 7;
  // Local source timestamps in ISO 8601 format without an offset.
  optional string source_created_at = 8;
  optional string source_modified_at = 9;
  FrameData attributes = 10;
  map<string, string> external_references = 11;
  repeated string linked_frame_ids = 12;
  optional string import_job_id = 13;
}

message FrameData {
  // Manual writes accept LIVE, PENDING, MAINTENANCE, BLOCKED, or DRAFT.
  string status = 1;
  optional string status_reason = 2;
  optional string site_no = 3;
  optional string inventory_site_no = 4;
  optional string panel_number = 5;
  optional string location_id = 6;
  optional string environment = 7;
  optional string address = 8;
  optional string station = 9;
  optional string airport = 10;
  // Decimal strings retain PostgreSQL numeric precision.
  optional string latitude = 11;
  optional string longitude = 12;
  optional int32 distance_to_closest_school = 13;
  FrameLocation location = 14;
  FrameFormat format = 15;
  optional string size_code = 16;
  optional string aspect_ratio_code = 17;
  optional string t_size = 18;
  optional int32 pixel_height = 19;
  optional int32 pixel_width = 20;
  optional int32 illumination_type_id = 21;
  optional int32 number_of_slots = 22;
  optional string impact_weight = 23;
  bool premium = 24;
  optional string production_rate_card = 25;
  optional string production_rate_card_legacy = 26;
  optional string pricing_grade = 27;
}

message FrameLocation {
  string country_code = 1;
  string region = 2;
  string town = 3;
  string postcode = 4;
}

message FrameFormat {
  // Manual writes accept CLASSIC or DIGITAL.
  string technology = 1;
  string format_code = 2;
  string size_group_code = 3;
}
package com.global.ct.frameinventory.frame;

import com.google.protobuf.Empty;
import io.grpc.stub.StreamObserver;
import jakarta.validation.ConstraintViolationException;
import jakarta.validation.Valid;
import jakarta.validation.Validator;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.spi.LoggingEventBuilder;
import org.springframework.stereotype.Service;

import com.global.ct.frameinventory.grpc.v1.CreateFrameRequest;
import com.global.ct.frameinventory.grpc.v1.DeleteFrameRequest;
import com.global.ct.frameinventory.grpc.v1.Frame;
import com.global.ct.frameinventory.grpc.v1.FrameManagementGrpc;
import com.global.ct.frameinventory.grpc.v1.GetFrameHistoryRequest;
import com.global.ct.frameinventory.grpc.v1.GetFrameHistoryResponse;
import com.global.ct.frameinventory.grpc.v1.GetFrameRequest;
import com.global.ct.frameinventory.grpc.v1.ListFramesRequest;
import com.global.ct.frameinventory.grpc.v1.ListFramesResponse;
import com.global.ct.frameinventory.grpc.v1.UpdateFrameRequest;

@Service
class FrameGrpcService extends FrameManagementGrpc.FrameManagementImplBase {
    private static final Logger LOGGER = LoggerFactory.getLogger(FrameGrpcService.class);

    private final FrameService frames;
    private final Validator validator;

    FrameGrpcService(FrameService frames, Validator validator) {
        this.frames = frames;
        this.validator = validator;
    }

    @Override
    public void listFrames(ListFramesRequest request, StreamObserver<ListFramesResponse> response) {
        var query = new PageQuery(request.getPage(), request.hasSize() ? request.getSize() : 25);
        LOGGER.atDebug()
            .addKeyValue("rpc", "ListFrames")
            .addKeyValue("page", query.page())
            .addKeyValue("size", query.size())
            .log("frame.rpc_received");
        validate(query);
        var page = frames.list(query.page(), query.size());
        var items = page.items().stream().map(FrameProtoMapper::toProto).toList();
        reply(response, ListFramesResponse.newBuilder()
            .addAllItems(items)
            .setPage(page.page())
            .setSize(page.size())
            .setHasNext(page.hasNext())
            .build());
    }

    @Override
    public void getFrame(GetFrameRequest request, StreamObserver<Frame> response) {
        requestLog("GetFrame", request.getFrameId()).log("frame.rpc_received");
        validate(new FrameId(request.getFrameId()));
        reply(response, FrameProtoMapper.toProto(frames.detail(request.getFrameId())));
    }

    @Override
    public void getFrameHistory(GetFrameHistoryRequest request, StreamObserver<GetFrameHistoryResponse> response) {
        requestLog("GetFrameHistory", request.getFrameId()).log("frame.rpc_received");
        validate(new FrameId(request.getFrameId()));
        var versions = frames.history(request.getFrameId()).stream().map(FrameProtoMapper::toProto).toList();
        reply(response, GetFrameHistoryResponse.newBuilder().addAllVersions(versions).build());
    }

    @Override
    public void createFrame(CreateFrameRequest request, StreamObserver<Frame> response) {
        requestLog("CreateFrame", request.getFrameId())
            .addKeyValue("hasAttributes", request.hasAttributes())
            .log("frame.rpc_received");
        var command = new Create(
            request.getFrameId(),
            request.hasAttributes() ? FrameProtoMapper.toAttributes(request.getAttributes()) : null
        );
        validate(command);
        reply(response, FrameProtoMapper.toProto(frames.create(command.frameId(), command.attributes())));
    }

    @Override
    public void updateFrame(UpdateFrameRequest request, StreamObserver<Frame> response) {
        requestLog("UpdateFrame", request.getFrameId())
            .addKeyValue("expectedVersionId", request.getExpectedVersionId())
            .addKeyValue("hasAttributes", request.hasAttributes())
            .log("frame.rpc_received");
        var command = new Update(
            request.getFrameId(),
            request.getExpectedVersionId(),
            request.hasAttributes() ? FrameProtoMapper.toAttributes(request.getAttributes()) : null
        );
        validate(command);
        reply(response, FrameProtoMapper.toProto(frames.edit(
            command.frameId(), command.expectedVersionId(), command.attributes()
        )));
    }

    @Override
    public void deleteFrame(DeleteFrameRequest request, StreamObserver<Empty> response) {
        var command = new Delete(
            request.getFrameId(), request.hasExpectedVersionId() ? request.getExpectedVersionId() : null
        );
        requestLog("DeleteFrame", command.frameId())
            .addKeyValue("expectedVersionId", command.expectedVersionId())
            .log("frame.rpc_received");
        validate(command);
        frames.delete(command.frameId(), command.expectedVersionId());
        reply(response, Empty.getDefaultInstance());
    }

    private static LoggingEventBuilder requestLog(String rpc, String frameId) {
        return LOGGER.atDebug()
            .addKeyValue("rpc", rpc)
            .addKeyValue("frameId", frameId.length() <= 128 ? frameId : "<oversize>");
    }

    private void validate(Object request) {
        var violations = validator.validate(request);
        if (!violations.isEmpty()) {
            throw new ConstraintViolationException(violations);
        }
    }

    private static <T> void reply(StreamObserver<T> response, T value) {
        response.onNext(value);
        response.onCompleted();
    }

    private record PageQuery(@PositiveOrZero int page, @Positive @Max(50) int size) {}

    private record FrameId(@NotBlank String frameId) {}

    private record Create(
        @NotBlank @Size(max = 128) @Pattern(regexp = "[^\\p{Cntrl}]+") String frameId,
        @NotNull @Valid FrameAttributes attributes
    ) {}

    private record Update(
        @NotBlank String frameId,
        @Positive long expectedVersionId,
        @NotNull @Valid FrameAttributes attributes
    ) {}

    private record Delete(@NotBlank String frameId, @Positive Long expectedVersionId) {}
}
package com.global.ct.frameinventory.frame;

import java.time.OffsetDateTime;
import java.util.List;

import com.global.ct.frameinventory.common.InventoryWriteLock;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Isolation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

@Service
class FrameService {
    private static final Logger LOGGER = LoggerFactory.getLogger(FrameService.class);

    private final FrameRepository frames;
    private final InventoryWriteLock inventoryLock;
    private final Counter framesCreated;
    private final Counter framesUpdated;
    private final Counter framesSoftDeleted;

    FrameService(FrameRepository frames, MeterRegistry registry, InventoryWriteLock inventoryLock) {
        this.frames = frames;
        this.inventoryLock = inventoryLock;
        this.framesCreated = lifecycleCounter(registry, "created");
        this.framesUpdated = lifecycleCounter(registry, "updated");
        this.framesSoftDeleted = lifecycleCounter(registry, "soft_deleted");
    }

    @Transactional(readOnly = true, isolation = Isolation.REPEATABLE_READ)
    FramePage list(int page, int size) {
        var matches = frames.list((long) page * size, size + 1);
        boolean hasNext = matches.size() > size;
        LOGGER.atInfo()
            .addKeyValue("page", page)
            .addKeyValue("size", size)
            .addKeyValue("totalElements", frames::countCurrent)
            .log("frame.listed");
        return new FramePage(hasNext ? List.copyOf(matches.subList(0, size)) : matches, page, size, hasNext);
    }

    FrameVersion detail(String frameId) {
        return frames.findCurrent(frameId).orElseThrow(FrameProblem::missing);
    }

    List<FrameVersion> history(String frameId) {
        var versions = frames.history(frameId);
        if (versions.isEmpty() && !frames.exists(frameId)) {
            throw FrameProblem.missing();
        }
        return versions;
    }

    @Transactional
    FrameVersion create(String frameId, FrameAttributes attributes) {
        inventoryLock.acquireShared();
        if (!frames.reserveId(frameId)) {
            throw FrameProblem.reserved();
        }
        long versionId = frames.append(frameId, attributes, null, null, "MANUAL_CREATE");
        FrameVersion created = frames.findVersion(versionId);
        afterCommit(() -> {
            framesCreated.increment();
            LOGGER.atInfo()
                .addKeyValue("frameId", frameId)
                .addKeyValue("versionId", versionId)
                .log("frame.created");
        });
        return created;
    }

    @Transactional
    FrameVersion edit(String frameId, long expectedVersionId, FrameAttributes attributes) {
        inventoryLock.acquireShared();
        Long current = lockAndCheckVersion(frameId, expectedVersionId);
        OffsetDateTime transition = frames.close(current, null);
        long versionId = frames.append(frameId, attributes, current, transition, "MANUAL_EDIT");
        frames.copyVersionChildren(current, versionId);
        FrameVersion updated = frames.findVersion(versionId);
        afterCommit(() -> {
            framesUpdated.increment();
            LOGGER.atInfo()
                .addKeyValue("frameId", frameId)
                .addKeyValue("previousVersionId", current)
                .addKeyValue("newVersionId", versionId)
                .log("frame.updated");
        });
        return updated;
    }

    @Transactional
    void delete(String frameId, Long expectedVersionId) {
        inventoryLock.acquireShared();
        Long current = lockAndCheckVersion(frameId, expectedVersionId);
        if (current != null) {
            frames.close(current, "MANUAL_DELETE");
            afterCommit(() -> {
                framesSoftDeleted.increment();
                LOGGER.atInfo()
                    .addKeyValue("frameId", frameId)
                    .addKeyValue("closedVersionId", current)
                    .log("frame.soft_deleted");
            });
        }
    }

    private Long lockAndCheckVersion(String frameId, Long expectedVersionId) {
        if (!frames.lockFrame(frameId)) {
            throw FrameProblem.missing();
        }
        Long current = frames.currentVersionId(frameId).orElse(null);
        LOGGER.atDebug()
            .addKeyValue("frameId", frameId)
            .addKeyValue("expectedVersionId", expectedVersionId)
            .addKeyValue("currentVersionId", current)
            .log("frame.version_checked");
        if (expectedVersionId != null && !expectedVersionId.equals(current)) {
            throw FrameProblem.stale(current);
        }
        return current;
    }

    private static Counter lifecycleCounter(MeterRegistry registry, String operation) {
        return Counter.builder("frame.lifecycle.changes")
            .description("Committed frame inventory changes")
            .tag("operation", operation)
            .register(registry);
    }

    private static void afterCommit(Runnable action) {
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
                @Override
                public void afterCommit() {
                    action.run();
                }
            });
        }
    }

    record FramePage(List<FrameVersion> items, int page, int size, boolean hasNext) {}
}
