const assert = require('node:assert/strict')
const { spawn } = require('node:child_process')
const { once } = require('node:events')
const { setTimeout } = require('node:timers/promises')
const { chromium } = require('/private/tmp/glo35-browser-test/node_modules/playwright')
const url = 'http://127.0.0.1:3419'

function frame(frameId, status = 'LIVE', town = 'Leeds') {
  return {
    __typename: 'Frame',
    frameId,
    attributes: {
      __typename: 'FrameAttributes',
      status,
      location: { __typename: 'FrameLocation', town, postcode: 'LS1 1AA' },
      address: null,
      siteNo: null,
      environment: null,
      format: null,
    },
  }
}

async function verify() {
  const server = spawn(process.execPath, [
    'node_modules/next/dist/bin/next', 'start', '--hostname', '127.0.0.1', '--port', '3419',
  ], { stdio: 'inherit' })
  let browser
  try {
    for (let attempt = 0; attempt < 40; attempt++) {
      if ((await fetch(url).catch(() => null))?.ok) break
      if (attempt === 39) throw new Error('Frontend did not start')
      await setTimeout(250)
    }
    browser = await chromium.launch({ channel: 'chrome', headless: true })
    const page = await browser.newPage()
    const errors = []
    page.on('pageerror', (error) => errors.push(error.message))
    const requests = []
    const rows = Array.from({ length: 31 }, (_, i) => frame('FRM-' + String(i + 1).padStart(3, '0')))
    rows[4] = frame('FRM-005', 'BLOCKED', 'London')
    rows[5] = frame('FRM-006', 'PENDING', 'London')
    rows.push(frame('TEST-LONDON-ID'))
    await page.route(url + '/api/graphql', async (route) => {
      const { variables } = route.request().postDataJSON()
      requests.push(variables)
      const { page, statuses = [], search = '' } = variables
      const term = search.toLowerCase()
      const matches = rows.filter(({ frameId, attributes }) =>
        (!statuses.length || statuses.includes(attributes.status)) &&
        [frameId, attributes.location.town].some((value) => value.toLowerCase().includes(term))
      )
      await setTimeout(200)
      await route.fulfill({ json: { data: { frames: {
        __typename: 'FramePage',
        page,
        size: 25,
        hasNext: (page + 1) * 25 < matches.length,
        items: matches.slice(page * 25, (page + 1) * 25),
      } } } })
    })
    const filter = page.getByRole('search', { name: 'Filter frames' })
    const search = filter.getByRole('searchbox', { name: 'Frame ID or town' })
    const next = page.getByRole('button', { name: 'Next' })
    const previous = page.getByRole('button', { name: 'Previous' })
    const live = filter.getByRole('checkbox', { name: 'Live', exact: true })
    const pending = filter.getByRole('checkbox', { name: 'Pending', exact: true })
    const apply = filter.getByRole('button', { name: 'Apply filters' })
    const clear = filter.getByRole('button', { name: 'Clear filters' })
    const history = (id) => page.getByRole('button', { name: 'View history for ' + id, exact: true })

    await page.goto(url)
    await history('FRM-001').waitFor()
    assert.deepEqual(requests.at(-1), { page: 0 })
    await next.click()
    await history('FRM-026').waitFor()
    assert.deepEqual(requests.at(-1), { page: 1 })

    await search.fill('  LoNd  ')
    await live.check()
    await pending.check()
    assert.deepEqual(requests.at(-1), { page: 1 })
    await search.press('Enter')
    await page.getByRole('status').getByText('Loading frames…').waitFor()
    assert.equal(await filter.isVisible(), true)
    await history('TEST-LONDON-ID').waitFor()
    assert.equal(await history('FRM-006').count(), 1)
    assert.equal(await history('FRM-005').count(), 0)
    assert.equal(await next.isDisabled(), true)
    assert.equal(await previous.isDisabled(), true)
    assert.deepEqual(requests.at(-1), { page: 0, search: 'LoNd', statuses: ['LIVE', 'PENDING'] })

    await search.fill('missing-frame')
    await apply.click()
    await page.getByRole('status').getByText('No frames match your filters.').waitFor()
    await clear.click()
    await history('FRM-001').waitFor()
    assert.equal(await search.inputValue(), '')
    assert.equal(await live.isChecked(), false)
    assert.equal(await pending.isChecked(), false)
    assert.deepEqual(requests.at(-1), { page: 0 })

    await live.check()
    await apply.click()
    await page.getByText('Showing 1–25').waitFor()
    assert.deepEqual(requests.at(-1), { page: 0, statuses: ['LIVE'] })
    await next.click()
    await history('TEST-LONDON-ID').waitFor()
    assert.deepEqual(requests.at(-1), { page: 1, statuses: ['LIVE'] })
    await previous.click()
    await history('FRM-001').waitFor()
    assert.deepEqual(requests.at(-1), { page: 0, statuses: ['LIVE'] })

    await page.setViewportSize({ width: 375, height: 812 })
    assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth))
    assert.equal(await apply.isVisible(), true)
    assert.deepEqual(errors, [])
    console.log('Verified desktop and mobile frame filters, GraphQL variables, loading, pagination, and clearing.')
  } finally {
    await browser?.close()
    if (server.exitCode === null) {
      server.kill('SIGTERM')
      await once(server, 'exit')
    }
  }
}
verify().catch((error) => {
  console.error(error)
  process.exitCode = 1
})
